package com.bank.roster;

public class OnCallRoster {

    public StaffNode rotateRight(StaffNode head, int k) {
        if (head == null || head.next == null || k == 0) return head;

        // 1) Find length and tail.
        int length = 1;
        StaffNode tail = head;
        while (tail.next != null) { tail = tail.next; length++; }

        // 2) Close into a ring.
        tail.next = head;

        // 3) Effective rotation; new tail is length - k%length steps from head.
        k = k % length;
        int stepsToNewTail = length - k;
        StaffNode newTail = head;
        for (int i = 1; i < stepsToNewTail; i++) newTail = newTail.next;

        // 4) Cut the ring.
        StaffNode newHead = newTail.next;
        newTail.next = null;
        return newHead;
    }
}
