package com.bank.roster;

import java.util.logging.Logger;

public class RotateDemo {
    private static final Logger log = Logger.getLogger(RotateDemo.class.getName());

    public static void main(String[] args) {
        StaffNode head = build(new int[]{1, 2, 3, 4, 5});
        log.info("Original roster: " + render(head));

        StaffNode out = new OnCallRoster().rotateRight(head, 2);
        log.info("Rotated right by 2: " + render(out));
    }

    static StaffNode build(int[] ids) {
        StaffNode d = new StaffNode(-1), t = d;
        for (int id : ids) { t.next = new StaffNode(id); t = t.next; }
        return d.next;
    }

    static String render(StaffNode n) {
        StringBuilder sb = new StringBuilder();
            while (n != null) { sb.append(n.staffId);
            if (n.next != null) sb.append(" -> "); n = n.next; }
        return sb.append(" -> null").toString();
    }
}
